const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
// Render a deliberately small Markdown subset. Never inject user/model HTML.
export function markdown(text){
 const inline=s=>escape(s).replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g,'<a href="$2" target="_blank" rel="noopener noreferrer">$1</a>').replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>').replace(/\*(.+?)\*/g,'<em>$1</em>').replace(/~~(.+?)~~/g,'<s>$1</s>');
 let code=false;return text.split('\n').map(line=>{if(line.startsWith('```')){code=!code;return code?'<pre><code>':'</code></pre>';}if(code)return escape(line)+'\n';if(/^#{1,6} /.test(line))return '<h3>'+inline(line.replace(/^#+ /,''))+'</h3>';if(/^[-*] /.test(line))return '<div class="chat-bullet">• '+inline(line.slice(2))+'</div>';if(/^> /.test(line))return '<blockquote>'+inline(line.slice(2))+'</blockquote>';return '<div>'+ (inline(line)||'<br>')+'</div>';}).join('')+(code?'</code></pre>':'');
}
export function enterAction(e){if(e.key!=='Enter'||e.isComposing||e.keyCode===229||e.altKey)return null;return e.ctrlKey||e.metaKey||e.shiftKey?'newline':e.repeat?'ignore':'send';}
let dialog,token,current,poll,revision=0,rendered='',opening=false;
const $=s=>dialog.querySelector(s);
async function api(body){if(!token){const r=await fetch('/api/study-token');token=(await r.json()).token;}const r=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json','X-Upheavel-Token':token},body:JSON.stringify(body)});if(r.status===403)token=null;let result;try{result=await r.json();}catch{throw new Error('Could not connect to study chat. Restart Projects.');}if(!r.ok)throw new Error(result.error||'Study request failed.');return result;}
function draftKey(){return 'upheavel.chat-draft.'+(current?.generation||'legacy')+'.'+current?.id;}
function saveDraft(){if(current)localStorage.setItem(draftKey(),$('#chat-input').value);}
function format(before,after=before){const input=$('#chat-input');input.focus();const start=input.selectionStart,end=input.selectionEnd,selected=input.value.slice(start,end);document.execCommand('insertText',false,before+selected+after);input.setSelectionRange(start+before.length,start+before.length+selected.length);saveDraft();preview();}
function preview(){const p=$('#chat-preview');if(!p.hidden)p.innerHTML=markdown($('#chat-input').value);}
function render(state){current.key=state.key;current.generation=state.generation;current.level=state.level;$('#lesson-level').value=state.level===null?'':String(state.level);$('#lesson-level').disabled=state.busy||opening;$('#chat-restart').disabled=state.busy||opening;const log=$('#chat-log'),nearBottom=log.scrollHeight-log.scrollTop-log.clientHeight<100;const json=JSON.stringify(state.messages);if(json!==rendered){rendered=json;log.innerHTML=state.messages.map((m,i)=>`<article class="chat-message ${m.role}"><div class="chat-author">${m.role==='user'?'You':'Luna'}<button data-copy="${i}" aria-label="Copy message">Copy</button></div><div class="chat-text">${markdown(m.text)}</div></article>`).join('')||'<p class="chat-empty">Start the lesson or write a question.</p>';log.messages=state.messages;annotateChoices();annotateWords();if(nearBottom)log.scrollTop=log.scrollHeight;}
 $('#chat-status').textContent=state.error||state.activity||(state.busy?'Thinking…':'Saved');$('#chat-send').disabled=state.busy||opening;$('#chat-start').hidden=state.messages.length>0;$('#chat-start').disabled=state.busy||opening;$('#chat-stop').hidden=!state.busy;
}
async function refresh(version){if(version!==revision||!dialog.open||!current.key)return;try{const state=await api({action:'state',key:current.key});if(version===revision)render(state);}catch(e){if(version===revision){$('#chat-status').textContent=e.message;return;}}if(version===revision)poll=setTimeout(()=>refresh(version),800);}
async function send(text=$('#chat-input').value){if(!text.trim()||!current.key||$('#chat-send').disabled)return;const version=revision;$('#chat-send').disabled=true;$('#chat-status').textContent='Sending…';try{const state=await api({action:'send',key:current.key,text});if(version!==revision)return;$('#chat-input').value='';saveDraft();preview();render(state);$('#chat-input').focus();}catch(e){if(version===revision){$('#chat-status').textContent=e.message;$('#chat-send').disabled=false;}}}
function annotateChoices(){
 $('#chat-log').querySelectorAll('.chat-message.assistant .chat-text').forEach(block=>{
  const rows=[...block.children].filter(row=>row.tagName==='DIV'&&!row.querySelector('a,code,pre'));
  const choices=rows.map(row=>({row,match:row.textContent.trim().match(/^([A-D])[.)]\s+\S/)})).filter(item=>item.match);
  if(!choices.some(item=>item.match[1]==='A')||!choices.some(item=>item.match[1]==='B'))return;
  for(const {row} of choices){const button=document.createElement('button');button.type='button';button.className='chat-choice';button.dataset.choice=row.textContent.trim();button.setAttribute('aria-label','Add to message: '+button.dataset.choice);button.title='Add to message without sending';button.append(...row.childNodes);row.replaceWith(button);}
 });
}
function insertChoice(text){
 const input=$('#chat-input');input.focus();input.setSelectionRange(input.value.length,input.value.length);
 const addition=(input.value&&!/\s$/.test(input.value)?'\n':'')+text;
 if(!document.execCommand('insertText',false,addition)){input.setRangeText(addition,input.value.length,input.value.length,'end');}
 saveDraft();preview();hideTranslation();
}
function setup(){
 const css=document.createElement('link');css.rel='stylesheet';css.href='/chat.css';document.head.append(css);
 dialog=document.createElement('dialog');dialog.id='study-chat';dialog.setAttribute('aria-labelledby','chat-title');dialog.innerHTML=`<div class="chat-heading"><div><h2 id="chat-title"></h2><span>Luna · 한국어 · Hover a word for English</span></div><div><label class="lesson-level">Difficulty<select id="lesson-level" aria-label="Lesson difficulty"><option value="">Profile</option><option value="1">TOPIK 1</option><option value="2">TOPIK 2</option><option value="3">TOPIK 3</option><option value="4">TOPIK 4</option><option value="5">TOPIK 5</option><option value="6">TOPIK 6</option></select></label><button id="chat-restart">Restart conversation</button><div class="chat-size-controls" role="group" aria-label="Text size"><button id="text-smaller" aria-label="Decrease text size">A−</button><label for="chat-text-size">Text size</label><input id="chat-text-size" type="range" min="12" max="32" step="1" value="18"><output id="text-size-value" for="chat-text-size">18px</output><button id="text-larger" aria-label="Increase text size">A+</button><button id="text-reset">Reset size</button></div><button id="chat-export">Export chat</button><button id="chat-close" aria-label="Close chat">×</button></div></div><div id="chat-log" tabindex="0" aria-label="Conversation"></div><div class="chat-compose"><div class="chat-toolbar" role="toolbar" aria-label="Message formatting"><button data-format="bold" title="Bold (Ctrl+B)"><b>B</b></button><button data-format="italic" title="Italic (Ctrl+I)"><i>I</i></button><button data-format="strike" title="Strikethrough">S̶</button><button data-format="heading">Heading</button><button data-format="bullet">• List</button><button data-format="number">1. List</button><button data-format="quote">Quote</button><button data-format="code">Code</button><button data-format="link" title="Link (Ctrl+K)">Link</button><button id="chat-preview-toggle" aria-pressed="false">Preview</button><button id="chat-shortcuts" aria-expanded="false">Shortcuts</button></div><div id="chat-help" hidden>Ctrl+B: bold · Ctrl+I: italic · Ctrl+K: link · Enter: send · Ctrl+Enter or Shift+Enter: new line<br>Ctrl+C/X/V: copy/cut/paste · Ctrl+A: select all in editor · Ctrl+Z/Y: undo/redo · Shift+arrows: select · Ctrl+arrows: move by word · Esc: close. Standard browser zoom, find and context menus are available.</div><label class="chat-input-label" for="chat-input">Message</label><textarea id="chat-input" placeholder="Write a message…" maxlength="50000" spellcheck="true"></textarea><div id="chat-preview" hidden></div><div class="chat-bottom"><span id="chat-status" role="status"></span><div><button id="chat-start">Start lesson</button><button id="chat-stop" hidden>Stop</button><button class="primary" id="chat-send">Send <small>Enter</small></button></div></div></div>`;document.body.append(dialog);const tip=document.createElement('div');tip.id='word-translation';tip.hidden=true;tip.setAttribute('role','status');dialog.append(tip);$('#chat-log').addEventListener('pointerover',wordEnter);$('#chat-log').addEventListener('focusin',wordEnter);$('#chat-log').addEventListener('pointerout',wordLeave);$('#chat-log').addEventListener('focusout',wordLeave);
 const sizeKey='upheavel.chat-text-size';
 function setTextSize(value){const size=Math.max(12,Math.min(32,Number(value)||18));dialog.style.setProperty('--chat-text-size',size+'px');$('#chat-text-size').value=String(size);$('#text-size-value').textContent=size+'px';$('#text-smaller').disabled=size===12;$('#text-larger').disabled=size===32;try{localStorage.setItem(sizeKey,String(size));}catch{}}
 let savedSize=18;try{savedSize=localStorage.getItem(sizeKey)||18;}catch{}setTextSize(savedSize);
 $('#chat-text-size').oninput=e=>setTextSize(e.target.value);$('#text-smaller').onclick=()=>setTextSize(Number($('#chat-text-size').value)-1);$('#text-larger').onclick=()=>setTextSize(Number($('#chat-text-size').value)+1);$('#text-reset').onclick=()=>setTextSize(18);
 $('#chat-close').onclick=()=>dialog.close();dialog.addEventListener('close',()=>{hideTranslation();saveDraft();revision++;clearTimeout(poll);});
 const formats={bold:['**','**'],italic:['*','*'],strike:['~~','~~'],heading:['### ',''],bullet:['- ',''],number:['1. ',''],quote:['> ',''],code:['`','`'],link:['[','](https://)']};
 dialog.querySelectorAll('[data-format]').forEach(b=>{b.onmousedown=e=>e.preventDefault();b.onclick=()=>format(...formats[b.dataset.format]);});
 $('#chat-input').oninput=()=>{saveDraft();preview();};$('#chat-input').onkeydown=e=>{if(e.isComposing||e.keyCode===229)return;const action=enterAction(e);if(action){e.preventDefault();if(action==='send')send();else if(action==='newline'){document.execCommand('insertText',false,'\n');saveDraft();preview();}return;}if(e.ctrlKey||e.metaKey){const k=e.key.toLowerCase();if(['b','i','k'].includes(k)){e.preventDefault();format(...formats[{b:'bold',i:'italic',k:'link'}[k]]);}}};
 $('#lesson-level').onchange=async e=>{const version=revision;const level=e.target.value===''?null:Number(e.target.value);e.target.disabled=true;try{const state=await api({action:'level',key:current.key,level});if(version===revision)render(state);}catch(error){if(version===revision){$('#chat-status').textContent=error.message;$('#lesson-level').value=current.level===null?'':String(current.level);$('#lesson-level').disabled=false;}}};
 $('#chat-restart').onclick=async()=>{if(!current.key||!confirm('Start a fresh conversation for this topic? Your chosen difficulty, level profile, and board notes will be kept. The old transcript stays on disk but will no longer be used here.'))return;saveDraft();hideTranslation();clearTimeout(poll);const version=++revision;opening=true;$('#chat-restart').disabled=true;$('#chat-send').disabled=true;$('#chat-status').textContent='Restarting…';try{const state=await api({action:'restart',key:current.key});if(version!==revision)return;opening=false;rendered='';$('#chat-input').value='';render(state);saveDraft();preview();refresh(version);}catch(error){if(version===revision){opening=false;$('#chat-status').textContent=error.message;$('#chat-restart').disabled=false;refresh(version);}}};
 $('#chat-send').onclick=()=>send();$('#chat-start').onclick=()=>send('선택한 난이도로 수업을 시작해 주세요. 문법이나 어휘 주제라면 설명 후 객관식 여섯 문제를 하나씩 내고, 그다음 영어 문장을 한국어로 옮기는 연습을 진행해 주세요.');
 $('#chat-stop').onclick=async()=>{try{render(await api({action:'stop',key:current.key}));}catch(e){$('#chat-status').textContent=e.message;}};
 $('#chat-preview-toggle').onclick=()=>{const p=$('#chat-preview');p.hidden=!p.hidden;$('#chat-preview-toggle').setAttribute('aria-pressed',String(!p.hidden));preview();};$('#chat-shortcuts').onclick=()=>{const h=$('#chat-help');h.hidden=!h.hidden;$('#chat-shortcuts').setAttribute('aria-expanded',String(!h.hidden));};
 $('#chat-log').onclick=async e=>{const choice=e.target.closest('[data-choice]');if(choice){insertChoice(choice.dataset.choice);return;}const button=e.target.closest('[data-copy]');if(button)try{await navigator.clipboard.writeText($('#chat-log').messages[Number(button.dataset.copy)].text);button.textContent='Copied';}catch{$('#chat-status').textContent='Select the message and press Ctrl+C to copy.';}};
 $('#chat-export').onclick=()=>{const text=(current.title+'\n\n'+($('#chat-log').messages||[]).map(m=>`## ${m.role==='user'?'You':'Luna'}\n\n${m.text}`).join('\n\n'));const url=URL.createObjectURL(new Blob([text],{type:'text/markdown;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='study-chat.md';a.click();URL.revokeObjectURL(url);};
}
export async function openChat(topic){if(!dialog)setup();if(dialog.open)saveDraft();clearTimeout(poll);const version=++revision;current={...topic};rendered='';opening=true;$('#chat-title').textContent=topic.title;$('#chat-log').innerHTML='';$('#chat-log').messages=[];$('#chat-input').value='';$('#chat-status').textContent='Loading saved conversation…';$('#chat-send').disabled=true;$('#lesson-level').disabled=true;$('#chat-restart').disabled=true;$('#chat-start').hidden=true;$('#chat-stop').hidden=true;preview();if(!dialog.open)dialog.showModal();$('#chat-input').focus();try{const state=await api({action:'open',topic});if(version!==revision)return;opening=false;render(state);$('#chat-input').value=localStorage.getItem(draftKey())||'';preview();refresh(version);}catch(e){if(version===revision){opening=false;$('#chat-status').textContent=e.message;}}}

let hoverTimer,hoverTarget,hoverSerial=0;
const dictionaryCache=new Map();
function annotateWords(){
 $('#chat-log').querySelectorAll('.chat-message.assistant .chat-text').forEach(block=>{
  const walker=document.createTreeWalker(block,NodeFilter.SHOW_TEXT);const nodes=[];while(walker.nextNode()){const node=walker.currentNode;if(!node.parentElement.closest('code,pre,.ko-word')&&/[가-힣ㄱ-ㅎㅏ-ㅣ]/.test(node.textContent))nodes.push(node);}
  for(const node of nodes){const fragment=document.createDocumentFragment();for(const part of node.textContent.split(/([가-힣ㄱ-ㅎㅏ-ㅣ]+)/g)){if(!part)continue;if(/^[가-힣ㄱ-ㅎㅏ-ㅣ]+$/.test(part)){const span=document.createElement('span');span.className='ko-word';span.textContent=part;span.tabIndex=node.parentElement.closest('.chat-choice')?-1:0;span.setAttribute('aria-label',part+' — English translation');fragment.append(span);}else fragment.append(document.createTextNode(part));}node.replaceWith(fragment);}
 });
}
function hideTranslation(){clearTimeout(hoverTimer);hoverSerial++;hoverTarget=null;if(dialog)$('#word-translation').hidden=true;}
function wordLeave(e){if(e.target.closest?.('.ko-word')&&!e.relatedTarget?.closest?.('#word-translation'))hideTranslation();}
function wordEnter(e){const word=e.target.closest?.('.ko-word');if(!word||word===hoverTarget)return;hideTranslation();hoverTarget=word;const serial=hoverSerial,version=revision;hoverTimer=setTimeout(async()=>{
 const article=word.closest('.chat-message'),articles=[...$('#chat-log').querySelectorAll('.chat-message')];const message=$('#chat-log').messages[articles.indexOf(article)];if(!message)return;
 const tip=$('#word-translation');tip.hidden=false;tip.textContent=word.textContent+' — Translating…';const cacheKey=current.key+'|'+message.id+'|'+word.textContent;
 try{let translation=dictionaryCache.get(cacheKey);if(!translation){const result=await api({action:'translate',key:current.key,messageId:message.id,word:word.textContent});translation=result.translation;dictionaryCache.set(cacheKey,translation);}if(serial===hoverSerial&&version===revision)tip.innerHTML=markdown(word.textContent+' — '+translation);}catch(error){if(serial===hoverSerial&&version===revision)tip.textContent=error.message;}
 },350);}
